function activityChart(rows) { let days = Array.from({ length: 7 }, (_, i) => { let d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - 6 + i); return d; }); let counts = days.map(d => rows.filter(s => new Date(s.completed_at) >= d && new Date(s.completed_at) < new Date(+d + 86400000)).length); let max = Math.max(4, ...counts), scale = Math.ceil(max / 4) * 4; return `<section class="card"><div class="card-head"><div><h2>Collection activity</h2><p class="card-note">Interviews completed over the last 7 days</p></div><span class="legend"><i></i>Submissions</span></div><div class="chart" role="img" aria-label="Daily submissions: ${counts.join(', ')}"><div class="gridlines">${[4, 3, 2, 1, 0].map(n => `<div class="gridline"><span>${scale * n / 4}</span></div>`).join('')}</div>${counts.map((n, i) => `<div class="bar-col"><div class="bar" style="height:${n / scale * 100}%"><span>${n || ''}</span></div><span class="bar-label">${days[i].toLocaleDateString(undefined, { weekday: 'short' })}</span></div>`).join('')}</div><div class="chart-footer"><span>${days[0].toLocaleDateString(undefined, { month: 'short', day: 'numeric' })} – ${date(new Date())}</span><span>${fmt(counts.reduce((a, n) => a + n, 0))} interviews this week</span></div></section>`; }
