function personCard(u, expanded = false, rows = null) { const m = u.last_seen ? (Date.now() - new Date(u.last_seen)) / 60000 : Infinity, status = !u.active ? 'Disabled' : m < 15 ? 'Active' : m < 120 ? 'Away' : 'Offline', count = rows ? rows.filter(s => s.user_id === u.id && s.consent === 'Yes').length : u.completed; return `<article class="person-card"><div class="person-top"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.community || 'Unassigned')}</small></div><i class="status-dot ${status === 'Active' ? '' : status === 'Away' ? 'idle' : 'offline'}" title="${status}" aria-label="${status}"></i></div><div class="person-stats"><span>Interviews completed</span><strong>${count} <span>/ ${u.target}</span></strong></div><div class="mini-progress"><i style="width:${u.target ? Math.min(count / u.target * 100, 100) : 0}%"></i></div><div class="person-foot">${icon('clock')} ${status} · ${relative(u.last_seen)}</div>${expanded ? `<div class="roster-extra">${esc(u.municipality_province || 'Municipality/province not set')}<br>${esc(u.language || 'Language not set')}<br>${u.location ? `${icon('pin')} Last shared location · ±${Math.round(u.location.accuracy)} m<br><a target="_blank" rel="noopener noreferrer" href="https://www.openstreetmap.org/?mlat=${u.location.lat}&mlon=${u.location.lng}#map=15/${u.location.lat}/${u.location.lng}">View recorded location ↗</a><br><small>${esc(fullDate(u.location.recorded_at))}</small>` : `${icon('pin')} No location shared`}<br><button class="btn" data-edit-user="${u.id}">${icon('settings')}Manage enumerator</button></div>` : ''}</article>`; }
