function originalReferenceCollectView() { return originalCollectView() + (!state.draft ? `<div class="card settings-card"><h2>Revised survey & field protocol</h2><p>${esc(schema.guidance)}</p><button class="btn" data-action="survey-protocol">Read sampling & enumerator protocol</button></div>` : ''); }
function collectView() { const html = originalReferenceCollectView(); return state.draft ? html : html.replace('<div class="field-start">', referenceReadinessView(true) + '<div class="field-start">'); }
const referenceCodes = { household: 'HE', community: 'CI', observation: 'SO' };
let referencePreparation = null;
function assignmentReady(user = state.user) { return user?.role === 'enumerator' && ['community', 'municipality_province', 'language'].every(k => typeof user[k] === 'string' && user[k].trim()); }
function referenceKey(user, instrument) { return user.id + ':' + instrument; }
function referenceRemaining(row, user = state.user) { return row?.status === 'ready' && row.user_id === user?.id ? Math.max(0, row.end - row.next + 1) : 0; }
