function originalInterviewView() { const d = state.draft, sections = interviewSections(), s = sections[state.step]; return heading(instrumentNames[d.instrument].toUpperCase(), `<button class="btn" data-action="save-exit">${icon('check')}Save & close</button>`) + `<div class="field-layout"><nav class="steps" aria-label="Interview sections">${sections.map((x, i) => `<button class="step ${i === state.step ? 'active' : ''}" data-step="${i}" ${d.consent !== 'Yes' && i > 0 && i !== sections.length - 1 ? 'disabled' : ''}><b>${x.id === '0' ? '1' : x.id === 'R' ? icon('check') : x.id}</b><span>${esc(x.title)}</span></button>`).join('')}</nav><div><section class="card survey-card"><div class="eyebrow">${state.step === 0 ? 'BEFORE WE BEGIN' : state.step === sections.length - 1 ? 'ONE LAST LOOK' : 'PART ' + s.id}</div><h2>${esc(s.title)}</h2><p class="card-note">${state.step === 0 ? 'Read the consent script exactly as written.' : state.step === sections.length - 1 ? 'Check the essentials, then send or queue this interview.' : 'Questions are optional. Leave an answer blank if the respondent skips it.'}</p><div id="questions">${state.step === 0 ? consentView() : state.step === sections.length - 1 ? reviewView() : s.questions.filter(q => !skipQuestion(q)).map(questionView).join('')}</div></section><div class="survey-nav"><button class="btn" data-action="back-step" ${state.step === 0 ? 'disabled' : ''}>← Back</button><span id="save-indicator">Saved on this device</span>${state.step === sections.length - 1 ? '<button class="btn primary" data-action="submit-survey">' + icon('check') + 'Finish interview</button>' : '<button class="btn primary" data-action="next-step">Continue ' + icon('arrow') + '</button>'}</div></div></div>`; }
