    if (options) return `<select class="input" ${attrs} aria-label="${esc(col.label)}"><option value="">—</option>${options.map(o => `<option value="${esc(o)}" ${value === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select>`;
    const number = col.type === 'number', integer = col.integer || ['qty', 'planned', 'interruptions'].includes(col.id) || id === 'A3';
