function originalReviewView() { const d = state.draft; return `<div class="detail-row"><span>Reference ID</span><strong>${esc(d.respondent || 'Missing — return to consent')}</strong></div><div class="detail-row"><span>Community</span><strong>${esc(d.community || 'Missing — return to consent')}</strong></div><div class="detail-row"><span>Interview consent</span><strong>${esc(d.consent || 'Not recorded')}</strong></div><div class="detail-row"><span>GPS consent / capture</span><strong>${esc(d.gps_consent)} · ${d.location ? 'Captured' : 'No location recorded'}</strong></div><div class="detail-row"><span>Questions with recorded answers</span><strong>${d.consent === 'No' ? 0 : countAnswers(d)}</strong></div><div class="detail-row"><span>Started</span><strong>${fullDate(d.started_at)}</strong></div><div class="notice" style="margin-top:22px">${d.consent === 'No' ? 'The respondent declined. No answers or GPS will be saved to the server.' : 'Skipped answers remain blank. Check appliance quantities, daily hours, and additional details before finishing.'}<br>${state.online ? 'The app will try to sync immediately.' : 'You are offline. This interview will be queued in this browser’s storage and sent after you reconnect and sign in.'}</div><label class="inline-check"><input type="checkbox" id="review-confirm">I have checked this interview and am ready to finish.</label>`; }
